import json
B={}

B["brandarchive-stella-artois-2023"]={"insights":"벨기에 맥주 스텔라 아르투아는 2023년 에이전시 JKR과 함께 1366년 양조 역사를 지키면서 더 젊고 동시대적인 인상을 주는 방향으로 브랜드를 재정비했다. 장식이 많던 카르투슈를 단순하게 정리하고 디지털 환경에 맞는 가로형 로고를 새로 도입했으며, 사냥용 뿔과 여덟 꼭짓점 별, 앤노 1366 같은 핵심 유산 요소는 그대로 남겼다. 팡그램 팡그램이 전용 서체 두 종을 제작하고 패션·라이프스타일 감성의 사진을 더해, 별을 강조하는 방사형 무늬가 캔과 병 전반에 따뜻하고 현대적인 결을 부여했다. 전통을 버리지 않고 다듬어 새로운 세대에게 다가가려는 절제된 진화였다."}

B["brandarchive-innocent-rebrand-2025"]={"insights":"이노센트는 기존 패키지가 소비자의 제품 선택을 어렵게 한다는 문제의식에서 2025년까지 18개 시장 전 주스·스무디 라인업을 새 디자인으로 교체했다. 디자인은 데릭앤에릭이 맡았으며, 브랜드 상징인 후광 쓴 듀드 로고를 다시 그려 패키지 전면 중심에 두고, 손그림 디테일과 자연스러운 과일 사진으로 사람이 만든 음료라는 인상을 강조했다. 두 가지 굵기의 이노센트 산스와 손글씨 서체 이노센트 핸드를 새로 만들어 친근하고 장난기 있는 톤을 살리고, 주스는 흰 배경의 과일 사진, 스무디는 농도를 암시하는 색조로 제품군을 구분했다. 창립 초기의 인간적이고 유쾌한 정체성을 복원하면서 진열대에서의 선택을 쉽게 하려는 변화다."}

B["brandarchive-bol"]={"insights":"BOL은 2014년 이노센트 출신 폴 브라운이 바쁜 사람도 식물성 식사를 쉽게 하도록 돕겠다는 목표로 세운 영국 즉석식 브랜드다. 2017년 육류와 생선을, 2018년 유제품을 빼며 완전 식물성으로 전환했다. 초기 패키지는 재료를 층층이 쌓아 보여주는 채소 일러스트로 신선함을 직관적으로 전했다. 2023년에는 재료 중심에서 라이프스타일 중심으로 슬로건을 옮겨갔다. 로고에서 따온 미소 형태를 활용하고 채소 대신 사람을 내세워 식물성 식생활의 긍정적 경험을 전면에 두는 방향으로 디자인을 재편했다."}

B["brandarchive-recchiuti-confections"]={
"overview":"레키우티 컨펙션스는 1997년 마이클 레키우티가 아내 재키와 함께 미국 샌프란시스코에서 설립한 수제 초콜릿 브랜드다. 필라델피아에서 나고 자란 그는 할머니의 부엌에서 이탈리아식 웨딩 케이크를 만들며 요리에 입문했고, 르 벡 팽에서 실력을 다듬은 뒤 설탕과 초콜릿 공예를 익혔다. 1987년 활기찬 음식·음악·예술 문화에 이끌려 샌프란시스코로 이주했고, 북부 캘리포니아의 신선한 지역 재료에서 새로운 영감을 얻었다. 1997년 창업 이후 전통 유럽식 기법으로 소량씩 손으로 빚는 방식을 고수해 왔다. 타라곤 자몽, 레몬 버베나, 스타 아니스와 핑크 페퍼콘처럼 향신료와 허브를 초콜릿에 접목한 독창적 풍미로 알려졌다. 페리 빌딩 마켓플레이스에 플래그십 매장을 두고 25년 넘게 샌프란시스코에서 초콜릿을 만들어 왔다.",
"insights":"레키우티의 철학은 정교한 장인정신과 재료에 대한 고집에 있다. 마이클 레키우티는 짠맛 계열의 향을 단맛에 더하는 실험을 통해 복합성과 우아함이 균형을 이루는 풍미를 추구해 왔고, 재료는 북부 캘리포니아의 농장과 시장에서 지역 조달한다. 창업 25년을 맞은 시점에 브랜드를 한층 온전히 표현하기 위해 샌프란시스코의 디자인 스튜디오 마누엘과 손잡고 전면 리브랜딩을 진행했다. 리브랜딩의 핵심 개념은 고객 인터뷰에서 거듭 등장한 표현인 숭고한 균형이다. 달콤함과 새콤함, 편안함과 발견, 친근함과 격식처럼 상반된 성질 사이의 정점을 찾아내는 능력을 가리킨다. 마누엘은 이 개념을 자연 재료를 예찬하는 손그림 선화와 통제된 스튜디오 사진을 나란히 배치해, 예술적 공예와 과학적 정밀함을 동시에 드러내는 방식으로 풀어냈다. 전자음악과 재즈를 다루는 음악가이기도 한 창업자의 면모를 시각 언어에 의도적으로 녹여 넣었다.",
"identity":"시각 아이덴티티의 중심은 율동하는 워드마크다. 글자의 올림 획과 내림 획이 교향곡을 연주하듯 위아래로 부드럽게 움직이며, 창업자의 음악적 배경을 반영한다. 일부 글자는 느긋하게 가라앉고 다른 글자의 줄기와 꼬리는 상자를 가로질러 뻗어 나간다. 활자는 타이트타입의 엑스포짓을 바탕으로 한다. 모노그램은 추상화된 균형판 위에 놓인 알파벳 R로, 숭고한 균형이라는 주제를 압축한다. 패키지는 상자, 바, 튜브로 이루어진 체계로 고급 종이와 견고한 구조, 다이아몬드 베벨 포일 엠보싱을 써 선물 같은 품격을 자아낸다. 전반적으로 단색조를 유지하되 풍미에 연동된 색을 군데군데 더한다. 스모어 키트에는 구운 마시멜로를 연상시키는 그러데이션을, 키 라임 페어에는 모노그램을 얹은 산뜻한 초록 스티커를 쓴다."}

B["brandarchive-juchheims"]={
"overview":"독일 카우프 출신 제과 장인 카를 유하임이 일본에 바움쿠헨을 처음 선보인 데서 출발한 고베의 양과자 브랜드다. 그는 1차 세계대전 포로로 일본에 온 뒤 정착해 1919년 히로시마에서 바움쿠헨을 구워 알렸고, 1922년 요코하마에 첫 매장을 열었다. 이듬해 관동대지진으로 점포를 잃자 고베로 옮겨 재기했다. 카를은 1945년 세상을 떠났으나 아내 엘리제가 사업을 이어 받았고, 오늘날 본사를 고베에 두고 창업 당시 제법을 지키며 바움쿠헨을 만든다.",
"identity":"2022년 일본 진출 100주년을 맞아 하쿠호도 디자인의 나가이 가즈후미가 이끈 리브랜딩을 단행했다. 새 로고는 창업자가 버터크림으로 짜 쓴 글씨를 토대로 가타카나를 더해 손맛을 되살렸다. 창업 초기부터 쓰던 흰색·빨강·검정 세 가지 색을 유하임 체크 패턴으로 부활시켰는데, 각각 순정 재료, 무첨가 제조, 장인의 계보를 뜻한다. 이 격자무늬는 매장 바닥과 포장, 쇼핑백 전반에 적용됐다."}

B["brandarchive-isle-of-wight-tomatoes-2023"]={
"overview":"아일오브와이트 토마토스는 영국 와이트섬에서 토마토를 재배하는 생산자가 2023년 리브랜드를 거쳐 새롭게 내세운 이름이다. 이 사업은 본래 더 토마토 스톨이라는 이름으로 알려졌으며, 섬에서 직접 기른 다양한 품종의 토마토와 이를 활용한 소스·조미료 등 가공식품을 함께 다룬다. 영국에서 일조 시간이 가장 길고 토양이 비옥한 와이트섬의 기후와 풍토를 바탕으로, 신선한 생토마토부터 토마토 기반 가공품까지 폭넓은 제품군을 갖추고 있다. 리브랜드와 함께 와이트섬이라는 산지 자체를 전면에 내세워, 영국 전역의 슈퍼마켓과 델리, 농장 매장, 레스토랑 그리고 자사 채널을 통해 제품을 공급한다. 단순한 농산물 공급자가 아니라 산지의 가치를 담은 브랜드로 스스로를 새롭게 자리매김한 점이 특징이다.",
"insights":"리브랜드의 핵심 과제는 가격으로 거래되는 일반 농산물에서 벗어나, 산지의 가치를 지닌 브랜드로 인식을 전환하는 것이었다. 디자인은 비앤비 스튜디오가 맡아 브랜드 포지셔닝과 전략, 패키지, 카피, 아트디렉션, 웹사이트까지 폭넓게 작업했다. 전략의 중심에는 영국에서 가장 긴 일조 시간과 비옥한 토양이라는 와이트섬 고유의 강점이 놓였고, 이는 더 많은 햇살, 더 진한 풍미라는 약속으로 압축되었다. 흔히 토마토에 기대하는 빨강과 초록 대신 햇살을 상징하는 노랑을 핵심 색으로 선택해 경쟁 제품과 시각적으로 차별화했고, 다양한 품종을 다룬다는 점도 색으로 암시했다. 브랜드 메시지는 무폐기물 철학과 천연 천적을 활용하는 지속 가능한 재배 방식 등 농장의 이야기로 확장되었다. 이러한 전환으로 유통업체와의 대화가 가격이 아닌 품질과 다양성 중심으로 바뀌었고, 출시 후 짧은 기간 안에 대형 유통망 입점과 매출 성장으로 이어졌다.",
"identity":"시각 정체성은 햇살을 상징하는 선명한 노랑을 핵심 색으로 삼아, 라벨과 패키지부터 인쇄물, 굿즈, 차량 래핑까지 전반에 일관되게 적용했다. 로고는 워드마크와 함께 토마토의 꽃받침에서 따온 초록색 별 모양 칼릭스 아이콘을 두어 품질과 산지를 상징하도록 구성했다. 워드마크에는 넓은 자간의 산세리프 서체를 써서 더 많은 햇살, 더 많은 풍미 같은 메시지를 강조했다. 패키지에서는 노랑을 기본으로 두되 소스와 조미료 등 가공품 라인에는 맛을 구분하는 색 팔레트를 도입하고, 초록 칼릭스로 전체를 하나로 묶었다. 밝고 자연광을 살린 사진을 더해 햇살 가득한 분위기를 일관되게 전달했다."}

B["brandarchive-agua-de-madre"]={
"overview":"아구아 데 마드레는 2017년 영국 런던에서 니콜라 하트가 자신의 이스트런던 주방에서 빚기 시작한 워터 케피어 음료 브랜드다. 워터 케피어는 물과 설탕에 케피어 그레인이라는 발효 종균을 배양해 만드는 약한 탄산 발효 음료로, 장 건강에 좋은 것으로 알려져 있다. 브랜드 이름의 마드레는 발효에 쓰이는 어머니 종균을 뜻하는 동시에 공동체를 일군 여성들을 기린다. 초기 제품은 모로 레스토랑의 샘 클라크와 함께 개발했으며, 저알코올 대안으로 런던의 여러 레스토랑과 바에 공급되며 자리를 잡았다. 런던 필즈와 해크니를 거점으로 소규모 배치로 양조하고, 워터 케피어 외에 인퓨전과 아구아 프레스카 등으로 제품군을 넓혔다. 여성이 창업한 브랜드로서 수익의 1퍼센트를 여성 중심 자선단체에 기부한다.",
"insights":"브랜드는 웰니스 카테고리의 전형인 미니멀리즘 대신 최대주의와 즐거움을 전략의 중심에 둔다. 장 건강이라는 기능적 메시지를 절제된 톤으로 전달하기보다, 어른을 위한 청량음료 진열대를 표방하며 감각적 과잉으로 차별화한다. 2025년 단행한 리브랜딩은 크리에이티브 디렉터 크리스 채프먼이 잰더 하트, 안야 란돌트와 함께 이끌었다. 이들은 마드레의 정신을 기리는 동시에 맛의 즐거움을 시각적으로 표현하는 것을 핵심 과제로 삼았다. 미니멀한 콤부차 경쟁자들과 대비되도록 강렬한 색과 겹쳐진 그래픽으로 시각적 충돌을 의도했고, 세대를 넘나드는 어린 시절의 거리낌 없는 환희를 끌어냈다. 동시에 기존 워드마크와 마드레 일러스트를 그대로 유지해 창업의 뿌리와 연속성을 지켰다. 발효 전통과 여성 공동체라는 서사를 디자인 언어로 번역해, 브랜드의 가치와 표현을 하나로 묶었다.",
"identity":"시각 시스템은 스티커를 마구 붙인 듯한 겹침 효과로 활기찬 충돌감을 만든다. 색은 귤빛 주황, 강렬한 청록, 핫핑크, 레몬옐로가 어우러져 최대치의 감각적 인상을 준다. 타이포그래피는 쿠퍼 블랙, ITC 바우하우스, 프랑크푸르터 하이라이트 등 서로 다른 서체를 섞어 1980년대 롤러 디스코부터 B급 공상과학까지 폭넓은 분위기를 낸다. 중심에는 원형 배지 안에 그려진 여성 일러스트가 자리해 중세기 광고와 라틴아메리카풍 감성을 떠올리게 한다. 그래픽은 종종 가독성의 경계에서 춤추듯 어지럽게 배열되어 긴장과 현대성을 더한다. 패키지는 무광과 유광 마감을 함께 써 촉각적 질감을 살린다."}

B["brandarchive-kisume"]={
"overview":"키스메는 호주 멜버른 중심부 플린더스 레인 175번지에 자리한 일식 파인다이닝 레스토랑이다. 친친 등으로 알려진 외식 그룹을 이끄는 크리스 루카스가 선보인 업장으로, 2017년 정식으로 문을 열었다. 한 건물의 세 개 층 전체를 사용하는 구조로, 지상층의 스시 바, 뜨거운 요리를 다루는 지하의 주방 공간, 그리고 샤블리 바와 프라이빗 다이닝, 12석 규모의 오마카세 공간을 갖춘 최상층으로 나뉜다. 전통 일식의 절제된 미감을 바탕에 두면서도 호주적인 감각을 더해, 격식 있는 일식당의 전형에서 의도적으로 벗어난 다이닝 경험을 지향한다.",
"insights":"키스메의 콘셉트는 디자인과 예술, 그리고 식문화를 하나의 경험으로 엮어내는 데 있다. 크리스 루카스는 전통 일본 건축의 단순함과 우아함을 가져오되 지루하지 않게 풀어내겠다는 방향을 제시했고, 이를 위해 멜버른의 건축 스튜디오 우드 마시와 협업했다. 세 개 층은 각각 성격이 다른 다이닝 무대로 기획되어, 손님이 층을 옮길 때마다 분위기와 메뉴의 결이 달라지도록 설계되었다. 정통 일식당에서 흔히 보이는 클리셰를 피하는 대신, 노부요시 아라키와 폴리 볼런드 같은 작가의 도발적인 사진 작업을 공간 곳곳에 배치해 예술적 긴장감을 더했다. 절제된 일식의 형식 위에 그룹 특유의 대담하고 다소 파격적인 감각을 입히는 전략이 키스메 전반을 관통한다.",
"identity":"키스메의 공간은 우드 마시가 설계한 무드 있고 미니멀한 미감을 따른다. 오크와 차콜 톤의 바닥, 검게 마감한 황동 디테일, 회색 가죽과 벨벳 등 어둡고 차분한 소재가 기조를 이루며, 붉은 외관과 원형 창이 강한 대비를 만든다. 지상층에는 조각적인 스시 바가, 최상층에는 와인 월을 갖춘 샤블리 바와 카이세키 공간이 놓인다. 노부요시 아라키와 폴리 볼런드의 사진 작업이 시각적 중심을 잡아주며, 절제된 건축과 강렬한 이미지의 긴장이 키스메 특유의 인상을 만든다."}

